import {storyContext,parseModelJSON,validateOutline} from './story.js';
import {digest} from './local-cache.js';
export async function outlineKey(p){return digest(JSON.stringify([p.title,p.author,p.language,p.genre,p.target,p.chapterCount||p.chapters.length,p.style,p.authorStyle,p.customAuthor,p.pov,p.tense,p.creativity,p.premise,p.world,p.characters,p.bible,p.styleNotes,p.references,p.frontMatter]));}
export const outlineStages=p=>1+Math.ceil((p.chapterCount||p.chapters.length)/4);
export function metadataPrompt(p){return `${storyContext(p)}\nPrepare the story foundation, without drafting chapters. Return only compact JSON {"characters":[{"name":"","role":"","wound":"","desire":"","need":"","contradiction":"","voice":""}],"bible":[{"name":"","type":"Location","detail":""}],"world":"","styleGuide":"","preface":""}. Supply at most 4 missing main characters and 5 missing world facts; retain supplied facts. Profiles: concise but specific. Style guide: 120 words maximum, including motifs, narrative distance and voice constraints. ${p.frontMatter?.includePreface===false?'Leave preface empty.':'Preface: 100–160 words.'} Do not write a chapter list yet. For nonfiction/poetry, use only appropriate people and factual world details. Every generated value must be in ${p.language}.`}
export function chaptersPrompt(p,work,start,count){return `${storyContext(p)}\nGENERATED FOUNDATION: ${JSON.stringify(work.metadata)}\nPREVIOUS PLAN: ${JSON.stringify(work.chapters)}\nPlan only chapters ${start+1} through ${start+count} of ${p.chapterCount||p.chapters.length}. Return ONLY compact JSON {"chapters":[{"title":"","beat":""}]}, exactly ${count} entries, in ${p.language}. Each beat: 45–75 words describing specific events, a change, consequences and continuity anchors. Preserve the preceding plan. Maintain pacing toward the final ending; the final planned chapter resolves the central arc. Never restart the story or copy an existing novel.`;}
function metadata(data,p){if(!data||!Array.isArray(data.characters)||data.characters.some(c=>!c||typeof c.name!=='string')||!Array.isArray(data.bible)||data.bible.some(x=>!x||typeof x.name!=='string'||typeof x.detail!=='string')||typeof data.world!=='string'||typeof data.styleGuide!=='string'||p.frontMatter?.includePreface!==false&&typeof data.preface!=='string')throw Error('The model returned an incomplete story foundation.');return data;}
export async function buildOutline(p,{request,checkpoint=()=>{},progress=()=>{},work=null,shouldStop=()=>false}){
 const key=await outlineKey(p),total=p.chapterCount||p.chapters.length;
 if(!work||work.key!==key)work={key,metadata:null,chapters:[],requests:0,recoveries:[],started:Date.now()};
 async function ask(prompt,label,validator){let lastError;for(let attempt=0;attempt<2;attempt++){
  if(shouldStop())throw Error('Outline paused. Your completed steps are saved; choose Generate outline to resume.');
  work.requests++;progress({label,completed:(work.metadata?1:0)+Math.floor(work.chapters.length/4),total:outlineStages(p),attempt,requests:work.requests});
  let raw='';try{raw=await request(prompt+(attempt?'\nYour earlier response was incomplete. Return a shorter complete JSON object with the same required fields, no code fences or commentary.':''),4096);const value=validator(parseModelJSON(raw));await checkpoint(work);return value;}
  catch(error){lastError=error;work.recoveries.push({stage:label,text:String(error.partialText||raw||'').slice(0,30000),message:error.message});work.recoveries=work.recoveries.slice(-3);await checkpoint(work);if(error.name!=='OutputLimitError'&&!(error instanceof SyntaxError)&&!/incomplete/.test(error.message))throw error;}
 }throw lastError;}
 if(!work.metadata){work.metadata=await ask(metadataPrompt(p),'Shaping characters, setting and voice',data=>metadata(data,p));await checkpoint(work);}
 while(work.chapters.length<total){const start=work.chapters.length,count=Math.min(4,total-start);const data=await ask(chaptersPrompt(p,work,start,count),`Planning chapters ${start+1}–${start+count}`,data=>{if(!data||!Array.isArray(data.chapters)||data.chapters.length!==count||data.chapters.some(c=>!c||typeof c.title!=='string'||!c.title.trim()||typeof c.beat!=='string'||!c.beat.trim()))throw Error('The model returned an incomplete chapter batch.');return data;});work.chapters.push(...data.chapters);await checkpoint(work);}
 return {data:validateOutline({...work.metadata,chapters:work.chapters},p),work};
}
export async function completeJSON(request,{prompt,maxTokens=4096,onRecovery=()=>{}}){let error;for(let attempt=0;attempt<2;attempt++){let raw='';try{raw=await request(prompt+(attempt?'\nReturn a shorter complete JSON object. Include the required fields, with concise values and no code fences.':''),maxTokens);return parseModelJSON(raw);}catch(e){error=e;if(e.name!=='OutputLimitError'&&!(e instanceof SyntaxError))throw e;await onRecovery({text:String(e.partialText||raw).slice(0,30000),message:e.message});}}throw error;}
